  %dot = "stablehlo.dot_general"(%arg3, %w_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: %arg2 shape is (7), need to broadcast to (6,7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Apply minimum with constant scalar %arg0
  // Broadcast constant scalar to (6,7)
  %const_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7xf32>

  %min_out = stablehlo.minimum %linear_out, %const_broadcast : tensor<6x7xf32>

  // Subtract constant scalar broadcasted
  %result = stablehlo.subtract %min_out, %const_broadcast : tensor<6x7xf32>

  return %result : tensor<6x7xf32>
}

