func.func @main(%multiplier: tensor<6x1x1xf32>, %conv_weight: tensor<6x6x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x6x7x7xf32>) -> tensor<6x6x5x5xf32> {
