  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // Actually, broadcast zero scalar to shape of scaled
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // The above is repeated, fix to one line:
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // Correct broadcast_in_dim for scalar to tensor<6x6x5x5xf32> is empty array
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x5x5xf32>
