  %cmax_tensor = "stablehlo.broadcast_in_dim"(%cmax) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %t10 = stablehlo.maximum %t9, %cmin_tensor : tensor<6x7xf32>
  %t11 = stablehlo.minimum %t10, %cmax_tensor : tensor<6x7xf32>

  // Tanh activation
  %t12 = stablehlo.tanh %t11 : tensor<6x7xf32>

  // Clamp again between -1.0 and 1.0
  %t13 = stablehlo.maximum %t12, %cmin_tensor : tensor<6x7xf32>
  %t14 = stablehlo.minimum %t13, %cmax_tensor : tensor<6x7xf32>

  return %t14 : tensor<6x7xf32>
}

