func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = bmm.weight (7x7)
  // %arg1 = bmm.bias (7)
  // %arg2 = input x (6x7)
  // %arg3 = input y (6x7)

  // Linear layer: x = x @ weight^T + bias
  // We need to do dot_general with contracting dims: x shape (6x7), weight shape (7x7)
  // PyTorch Linear does x @ weight^T + bias, so we transpose weight to (7x7) -> (7x7) (square, so transpose is same shape)
  // But we must do x @ weight^T, so contract x dim 1 with weight dim 1 (the second dim of weight)
  // So lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]
  // lhs_batching_dimensions = [0], rhs_batching_dimensions = [0]
  // Result shape: batch dims (0) + lhs dims except contracting (0) + rhs dims except contracting (0)
  // lhs dims: 6x7, contracting dim 1, so lhs remaining dim 0=6
  // rhs dims: 7x7, contracting dim 1, so rhs remaining dim 0=7
  // Result shape: 6x7

  // Transpose weight to get weight^T (7x7) -> (7x7) with permutation [1,0]
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  %bmm_out = "stablehlo.dot_general"(%arg2, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [0],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bmm_bias = stablehlo.add %bmm_out, %bias_broadcast : tensor<6x7xf32>

  // InstanceNorm2d on x.unsqueeze(1).unsqueeze(1)
  // x shape: (6x7)
  // unsqueeze(1) twice -> shape (6x1x1x7)
  // So reshape to (6x1x1x7)
  %x_4d = stablehlo.reshape %bmm_bias : (tensor<6x7xf32>) -> tensor<6x1x1x7xf32>

  // InstanceNorm2d parameters:
  // eps=1e-5, momentum=0.1 (momentum unused in forward)
  // InstanceNorm2d normalizes per instance per channel:
  // For input (N,C,H,W), normalize each sample n and channel c over H*W elements:
  // mean = sum over H,W of x[n,c,h,w] / (H*W)
  // var = sum over H,W of (x[n,c,h,w] - mean)^2 / (H*W)
  // output = (x - mean) / sqrt(var + eps)

  // Here N=6, C=1, H=1, W=7
  // Actually shape is (6,1,1,7), so normalization is over dims [2,3] (H,W)
  // But PyTorch InstanceNorm2d normalizes over spatial dims (H,W), so dims 2 and 3

  // Compute mean over dims 2 and 3 (H and W)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32> // scalar zero

  %mean = "stablehlo.reduce"(%x_4d, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // mean shape: (6x1x1) after reduction dims 2,3 removed -> (6x1)
  // Actually dims 2 and 3 removed, so shape (6x1)

  // Compute divisor = H*W = 1*7 = 7.0
  %seven = stablehlo.constant dense<7.0> : tensor<f32>

  // Divide mean by 7.0
  %mean_div = stablehlo.divide %mean, %seven : tensor<6x1xf32>

  // Broadcast mean_div back to (6x1x1x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x1xf32>) -> tensor<6x1x1x7xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %x_4d, %mean_broadcast : tensor<6x1x1x7xf32>

  // Compute squared difference
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x1x1x7xf32>

  // Compute variance: reduce sum over dims 2,3
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>

  %var_sum = "stablehlo.reduce"(%x_centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // var = var_sum / 7.0
  %var = stablehlo.divide %var_sum, %seven : tensor<6x1xf32>

  // Add eps=1e-5 to var
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<6x1xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x1xf32>

  // Broadcast stddev to (6x1x1x7)
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x1xf32>) -> tensor<6x1x1x7xf32>

  // Normalize: (x - mean) / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast : tensor<6x1x1x7xf32>

  // Squeeze dims 1 and 2: (6x1x1x7) -> (6x7)
  // First reshape to (6x7)
  %x_norm_2d = stablehlo.reshape %x_norm : (tensor<6x1x1x7xf32>) -> tensor<6x7xf32>

  // Add residual: x_norm_2d + y (%arg3)
  %add_res = stablehlo.add %x_norm_2d, %arg3 : tensor<6x7xf32>

  // Multiply by y: (x_norm_2d + y) * y
  %mul_res = stablehlo.multiply %add_res, %arg3 : tensor<6x7xf32>

  // Return result
  return %mul_res : tensor<6x7xf32>
}

