func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %0 = gemm: input @ input_weight^T + bias
  // dot_general with contracting dims: input last dim 1, weight last dim 0 (transpose)
  %0 = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1], lhs_batching_dimensions = [0], rhs_batching_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %1 = stablehlo.add %0, %bias : tensor<6x7xf32>

  // %2 = scale multiply: x * scale
  // broadcast scale (7) to (6x7) on dim 1
  %2 = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %3 = stablehlo.multiply %1, %2 : tensor<6x7xf32>

  // BatchNorm1d forward training mode:
  // Compute mean and variance over batch dimension (dim 0)
  // mean = reduce mean over dim 0
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%3, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %c6 = stablehlo.constant dense<6.0> : tensor<f32>
  %c6_bcast = "stablehlo.broadcast_in_dim"(%c6) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.divide %sum, %c6_bcast : tensor<7xf32>

  // Compute variance = mean((x - mean)^2) over batch dim 0
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %3, %mean_bcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add2 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %c6_bcast : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.00000001e-05> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>
  %rsqrt_var_eps = stablehlo.rsqrt %var_eps : tensor<7xf32>
  %rsqrt_var_eps_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff_norm = stablehlo.multiply %diff, %rsqrt_var_eps_bcast : tensor<6x7xf32>

  // Scale and shift: bn_weight * normalized + bn_bias
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %diff_norm, %bn_weight_bcast : tensor<6x7xf32>
  %out = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

