func.func @main(%conv_weight: tensor<16x3x4x4x4xf32>, %conv_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x16xf32> {
  // 1. Convolution
  // conv: input (6x3x16x7x7), weight (16x3x4x4x4), bias (16)
  // dimension_numbers: input [b, f, d, h, w] = [0,1,2,3,4]
  // kernel [o, i, kd, kh, kw] = [0,1,2,3,4]
  // output [b, f, d, h, w] = [0,1,2,3,4]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x4x4x4xf32>) -> tensor<6x16x13x4x4xf32>

  // 2. Add bias: broadcast conv_bias (16) to conv output shape (6x16x13x4x4)
  %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<6x16x13x4x4xf32>
  %conv_biased = stablehlo.add %conv, %conv_bias_bcast : tensor<6x16x13x4x4xf32>

  // 3. HardSwish activation: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
