  %mul_weight_bcast = "stablehlo.broadcast_in_dim"(%multiply_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %mul = stablehlo.multiply %swish1, %mul_weight_bcast : tensor<16x16xf32>

  // Swish again: mul * sigmoid(mul)
  %neg_mul = stablehlo.negate %mul : tensor<16x16xf32>
  %exp_neg_mul = stablehlo.exponential %neg_mul : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_bcast, %exp_neg_mul : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_bcast, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %mul, %sigmoid2 : tensor<16x16xf32>

  stablehlo.return %swish2 : tensor<16x16xf32>
}

func.func @main(%multiply_weight: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %group_norm_weight: tensor<16xf32>, %group_norm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // GEMM: x = input @ gemm_weight^T + gemm_bias
  // gemm_weight shape: [16,16], input shape: [16,16]
  // We want to do dot_general with contracting dims: input dim 1 and gemm_weight dim 1 (transposed)
  // So transpose gemm_weight to [16x16] -> [16x16] with permutation [1,0]
  %gemm_weight_t = "stablehlo.transpose"(%gemm_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %gemm_out = "stablehlo.dot_general"(%input, %gemm_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Broadcast gemm_bias [16] to [16x16] on dim 1
  %gemm_bias_bcast = "stablehlo.broadcast_in_dim"(%gemm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gemm_out_biased = stablehlo.add %gemm_out, %gemm_bias_bcast : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, out_features = 16, so each group has 1 channel (16/16=1)
  // Reshape to [batch, groups, channels_per_group] = [16,16,1]
  %gn_reshape1 = stablehlo.reshape %gemm_out_biased : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gn_reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by channels_per_group=1 (no-op)
  // mean shape: [16,16]

  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to [16,16,1]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %gn_reshape1, %mean_bcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %zero_f32_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by channels_per_group=1 (no-op)
  // var shape: [16,16]

  // Compute inv_std = rsqrt(var + epsilon)
  %epsilon_scalar = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  // Broadcast epsilon to [16x16]
  %epsilon = "stablehlo.broadcast_in_dim"(%epsilon_scalar) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %epsilon : tensor<16x16xf32>
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %diff_2 = stablehlo.subtract %gn_reshape1, %mean_bcast : tensor<16x16x1xf32>
  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %norm = stablehlo.multiply %diff_2, %inv_std_bcast : tensor<16x16x1xf32>

  // Reshape norm back to [16x16]
  %norm_reshaped = stablehlo.reshape %norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply affine transform: norm * group_norm_weight + group_norm_bias
  // group_norm_weight and bias shape: [16]
  // Broadcast to [16x16]
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%group_norm_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%group_norm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %affine = stablehlo.add (stablehlo.multiply %norm_reshaped, %gn_weight_bcast : tensor<16x16xf32>), %gn_bias_bcast : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_affine = stablehlo.negate %affine : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg_affine : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %denom = stablehlo.add %one_bcast, %exp_neg : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16xf32>
  %swish1 = stablehlo.multiply %affine, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (shape [16]) broadcasted on dim 1
  %mul_weight_bcast = "stablehlo.broadcast_in_dim"(%multiply_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %mul = stablehlo.multiply %swish1, %mul_weight_bcast : tensor<16x16xf32>

  // Swish again: mul * sigmoid(mul)
  %neg_mul = stablehlo.negate %mul : tensor<16x16xf32>
  %exp_neg_mul = stablehlo.exponential %neg_mul : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_bcast, %exp_neg_mul : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_bcast, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %mul, %sigmoid2 : tensor<16x16xf32>

  stablehlo.return %swish2 : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Perform convolution:
  // Input: %arg2 (N=6, C=8, H=6, W=6)
  // Weight: %arg0 (O=7, I=8, KH=3, KW=3)
  // Bias: %arg1 (7)
  // PyTorch Conv2d default stride=1, padding=0, dilation=1, groups=1
  // Output shape: (6,7,4,4) as given

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 0, 1]x[o, i, 2, 3]->[b, o, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add bias: %arg1 shape is [7], need to broadcast to [6x7x4x4]
  // Broadcast bias to [1x7x1x1]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  // Broadcast to output shape [6x7x4x4]
  %bias_bcast_full = "stablehlo.broadcast_in_dim"(%bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_bcast_full : tensor<6x7x4x4xf32>

  // Divide by divisor=2 (constant scalar)
  %c_divisor = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast divisor scalar to output shape
  %divisor_bcast = "stablehlo.broadcast_in_dim"(%c_divisor) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %div = stablehlo.divide %conv_bias, %divisor_bcast : tensor<6x7x4x4xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0, x) + negative_slope * min(0, x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %max_part = stablehlo.maximum %div, %zero_bcast : tensor<6x7x4x4xf32>
  %min_part = stablehlo.minimum %div, %zero_bcast : tensor<6x7x4x4xf32>
  %c_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %slope_bcast = "stablehlo.broadcast_in_dim"(%c_slope) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %scaled_min = stablehlo.multiply %min_part, %slope_bcast : tensor<6x7x4x4xf32>
  %leaky_relu = stablehlo.add %max_part, %scaled_min : tensor<6x7x4x4xf32>

  return %leaky_relu : tensor<6x7x4x4xf32>
}

