func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0 = bias (tensor<16xf32>)
  // %arg1 = matmul.weight (tensor<16x16xf32>)
  // %arg2 = matmul.bias (tensor<16xf32>)
  // %arg3 = group_norm.weight (tensor<16xf32>)
  // %arg4 = group_norm.bias (tensor<16xf32>)
  // %arg5 = input (tensor<16x16xf32>)

  // Step 1: matmul: x = matmul(input, weight^T)
  // matmul.weight shape: [16,16], input shape: [16,16]
  // We want to do x = input @ weight^T
  // So transpose weight to [16,16] (same shape, but swap dims)
  %t0 = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %x = "stablehlo.dot_general"(%arg5, %t0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: Swish activation: x = sigmoid(x) * x
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = stablehlo.negate %x : tensor<16x16xf32>
  %exp_neg_x = stablehlo.exponential %neg_x : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  // Broadcast 1.0 to tensor<16x16xf32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %denom = stablehlo.add %one_bcast, %exp_neg_x : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16xf32>
  %swish = stablehlo.multiply %sigmoid, %x : tensor<16x16xf32>

  // Step 3: add bias (bias shape: [16], add to last dim)
  // Broadcast bias to [16x16]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_bias = stablehlo.add %swish, %bias_bcast : tensor<16x16xf32>

  // Step 4: group norm
  // group_norm parameters:
  // num_groups = 16, out_features = 16
  // input shape: [batch=16, channels=16]
  // GroupNorm with num_groups=16 means each channel is its own group (group size = 1)
  // So normalization is per channel per batch element, but since group size=1, variance=0 always
  // We must compute mean and variance per group (per batch and group)
  // Reshape x_bias to [batch=16, groups=16, group_size=1]
  %x_reshaped = stablehlo.reshape %x_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over group_size dim (dim=2)
  // init value for add reduce: 0.0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_scalar = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %mean = "stablehlo.reduce"(%x_reshaped, %zero_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide sum by group_size=1 (no change)
  // mean shape: [16x16]

  // Compute variance: mean of (x - mean)^2 over group_size dim
  // Broadcast mean to [16x16x1]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %x_reshaped, %mean_bcast : tensor<16x16x1xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var_sum = "stablehlo.reduce"(%sq_diff, %zero_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = var_sum / group_size=1 (no change)
  %var = %var_sum : tensor<16x16xf32>

  // Compute inv_std = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x16xf32>
  %std = stablehlo.sqrt %var_eps : tensor<16x16xf32>
  %inv_std = stablehlo.divide %one_bcast, %std : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  // Broadcast mean and inv_std to [16x16x1]
  // Already have mean_bcast and inv_std_bcast
  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %normalized = stablehlo.multiply %diff, %inv_std_bcast : tensor<16x16x1xf32>

  // Reshape normalized back to [16x16]
  %normalized_2d = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply affine transform: normalized * weight + bias
