    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // 2) Add bias: broadcast bias from [6] to [6x6x4x4]
  // Broadcast bias on feature dimension (dim=1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x1x1xf32>
  // Broadcast to full conv output shape [6x6x4x4]
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast_full : tensor<6x6x4x4xf32>

  // 3) Subtract 0.5 (subtract_value)
  %c_subtract = stablehlo.constant dense<0.5> : tensor<f32>
  %c_subtract_tensor = "stablehlo.broadcast_in_dim"(%c_subtract) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub = stablehlo.subtract %conv_bias, %c_subtract_tensor : tensor<6x6x4x4xf32>

  // 4) HardSwish: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  %c_3 = stablehlo.constant dense<3.0> : tensor<f32>
  %c_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c_6 = stablehlo.constant dense<6.0> : tensor<f32>
  %c_6_tensor = "stablehlo.broadcast_in_dim"(%c_6) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %c_0_tensor = "stablehlo.broadcast_in_dim"(%c_0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %c_3_tensor = "stablehlo.broadcast_in_dim"(%c_3) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %add3 = stablehlo.add %sub, %c_3_tensor : tensor<6x6x4x4xf32>
  %max0 = stablehlo.maximum %add3, %c_0_tensor : tensor<6x6x4x4xf32>
  %min6 = stablehlo.minimum %max0, %c_6_tensor : tensor<6x6x4x4xf32>
  %mul = stablehlo.multiply %sub, %min6 : tensor<6x6x4x4xf32>
  %c_6_inv = stablehlo.constant dense<0.16666667> : tensor<f32>  // 1/6
  %c_6_inv_tensor = "stablehlo.broadcast_in_dim"(%c_6_inv) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %hardswish = stablehlo.multiply %mul, %c_6_inv_tensor : tensor<6x6x4x4xf32>

  // 5) MaxPool2d with kernel=2, stride=2, no padding
  // Use reduce_window with maximum
  %init = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf in f32 bit pattern
  %maxpool = "stablehlo.reduce_window"(%hardswish, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // 6) Mish activation: x * tanh(ln(1 + exp(x)))
  // Compute exp(x)
  %exp = stablehlo.exponential %maxpool : tensor<6x6x2x2xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %exp_plus_one = stablehlo.add %exp, %one_tensor : tensor<6x6x2x2xf32>
  %log = stablehlo.log %exp_plus_one : tensor<6x6x2x2xf32>
  %tanh = stablehlo.tanh %log : tensor<6x6x2x2xf32>
  %mish = stablehlo.multiply %maxpool, %tanh : tensor<6x6x2x2xf32>

  stablehlo.return %mish : tensor<6x6x2x2xf32>
}

func.func @main(%x: tensor<9xf32>) -> tensor<9xf32> {
  %c_min = stablehlo.constant dense<-1.0> : tensor<f32>
  %c_max = stablehlo.constant dense<0.0> : tensor<f32>
  %r = "stablehlo.clamp"(%c_min, %x, %c_max) : (tensor<f32>, tensor<9xf32>, tensor<f32>) -> tensor<9xf32>
  return %r : tensor<9xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x = input @ weight^T + bias
  // weight is (7x7), input is (6x7)
  // We want input (6x7) dot weight^T (7x7) -> (6x7)
  // So transpose weight to (7x7) (actually same shape, but transpose swaps dims)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm_dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_out = "stablehlo.add"(%gemm_dot, %bias_bcast) : tensor<6x7xf32>

  // BatchNorm1d: (training mode)
  // y = (x - mean) / sqrt(var + eps) * weight + bias
  // mean and var computed per feature (dim=0) over batch dimension (6)
  // Compute mean over dim 0 (batch dimension)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>  // scalar zero
  %mean = "stablehlo.reduce"(%gemm_out, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean shape: (7)

  // Compute mean * batch_size (6) as float constant
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  // Broadcast six to (7)
  %six_bcast = "stablehlo.broadcast_in_dim"(%six_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Actually we want to divide mean by 6, so invert 6
  %inv_six = stablehlo.constant dense<0.16666667> : tensor<f32>
  // Broadcast inv_six to (7)
  %inv_six_bcast = "stablehlo.broadcast_in_dim"(%inv_six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // mean = mean * inv_six
  %mean_scaled = "stablehlo.multiply"(%mean, %inv_six_bcast) : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // First broadcast mean (7) to (6x7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = "stablehlo.subtract"(%gemm_out, %mean_bcast) : tensor<6x7xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // var = var_sum * inv_six
  %var = "stablehlo.multiply"(%var_sum, %inv_six_bcast) : tensor<7xf32>

  // eps = 1e-5 constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>

  // var + eps
  %var_eps = "stablehlo.add"(%var, %eps_bcast) : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = "stablehlo.sqrt"(%var_eps) : tensor<7xf32>

  // Broadcast stddev to (6x7)
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  %normed = "stablehlo.divide"(%diff, %stddev_bcast) : tensor<6x7xf32>

  // Apply batch_norm.weight and batch_norm.bias
  // Broadcast batch_norm.weight (7) to (6x7)
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = "stablehlo.multiply"(%normed, %bn_weight_bcast) : tensor<6x7xf32>
  // Broadcast batch_norm.bias (7) to (6x7)
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %batchnorm_out = "stablehlo.add"(%scaled, %bn_bias_bcast) : tensor<6x7xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %sqrt2_bcast_6x7 = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %inv_sqrt2 = stablehlo.constant dense<0.70710677> : tensor<f32>
  %inv_sqrt2_bcast = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %inv_sqrt2_bcast_6x7 = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %inv_sqrt2_bcast_6x7 = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  // Actually just broadcast inv_sqrt2 to (6x7)
  %inv_sqrt2_bcast_6x7 = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %x_div_sqrt2 = "stablehlo.multiply"(%batchnorm_out, %inv_sqrt2_bcast_6x7) : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_s

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x = input @ weight^T + bias
  // weight is (7x7), input is (6x7)
  // We want input (6x7) dot weight^T (7x7) -> (6x7)
  // So transpose weight to (7x7) (actually same shape, but transpose swaps dims)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm_dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_out = "stablehlo.add"(%gemm_dot, %bias_bcast) : tensor<6x7xf32>

  // BatchNorm1d: (training mode)
  // y = (x - mean) / sqrt(var + eps) * weight + bias
  // mean and var computed per feature (dim=0) over batch dimension (6)
  // Compute mean over dim 0 (batch dimension)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_out, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Divide mean by batch size 6
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %mean_scaled = "stablehlo.divide"(%mean, %six_bcast) : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // Broadcast mean (7) to (6x7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = "stablehlo.subtract"(%gemm_out, %mean_bcast) : tensor<6x7xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = "stablehlo.divide"(%var_sum, %six_bcast) : tensor<7xf32>

  // eps = 1e-5 constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>

  // var + eps
  %var_eps = "stablehlo.add"(%var, %eps_bcast) : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = "stablehlo.sqrt"(%var_eps) : tensor<7xf32>

  // Broadcast stddev to (6x7)
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  %normed = "stablehlo.divide"(%diff, %stddev_bcast) : tensor<6x7xf32>

  // Apply batch_norm.weight and batch_norm.bias
  // Broadcast batch_norm.weight (7) to (6x7)
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = "stablehlo.multiply"(%normed, %bn_weight_bcast) : tensor<6x7xf32>
  // Broadcast batch_norm.bias (7) to (6x7)
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %batchnorm_out = "stablehlo.add"(%scaled, %bn_bias_bcast) : tensor<6x7xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // inv_sqrt2 = 1 / sqrt(2)
  %inv_sqrt2 = stablehlo.constant dense<0.70710677> : tensor<f32>
  %inv_sqrt2_bcast = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %inv_sqrt2_bcast_6x7 = "stablehlo.broadcast_in_dim"(%inv_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %x_div_sqrt2 = "stablehlo.multiply"(%batchnorm_out, %inv_sqrt2_bcast_6x7) : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x7xf32>

  // 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_erf = "stablehlo.add"(%one_bcast, %erf) : tensor<6x7xf32>

  // x * 0.5
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %x_times_half = "stablehlo.multiply"(%batchnorm_out, %half_bcast) : tensor<6x7xf32>

  // GELU output = x * 0.5 * (1 + erf(...))
  %gelu_out = "stablehlo.multiply"(%x_times_half, %one_plus_erf) : tensor<6x7xf32>

  // ReLU activation: max(0, x)
  %zero_6x7 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero_6x7) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %relu_out = "stablehlo.maximum"(%gelu_out, %zero_bcast) : tensor<6x7xf32>

  return %relu_out : tensor<6x7xf32>
}

func.func @main(%subtract: tensor<16xf32>, %conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x16x7x7xf32> {
  // 1) ConvTranspose3d: implemented as convolution with lhs_dilation=2 (stride=2), rhs_dilation=1, padding=1, output_padding=1
  // dimension_numbers: input [b, i, d, h, w], kernel [i, o, kd, kh, kw] for conv_transpose PyTorch
  // StableHLO convolution dimension_numbers: lhs [b, f, 0, 1, 2], rhs [o, i, 0, 1, 2] -> [b, f, 0, 1, 2]
  // We must transpose conv_transpose_weight from [3,16,3,3,3] (i,o,kd,kh,kw) to [16,3,3,3,3] (o,i,kd,kh,kw)
  // So first reshape and transpose conv_transpose_weight

  // Reshape conv_transpose_weight to 5D tensor (already 5D)
  // Transpose dims: from [i,o,d,h,w] to [o,i,d,h,w] = permute [1,0,2,3,4]
  %weight_transposed = "stablehlo.transpose"(%conv_transpose_weight) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Convolution with lhs_dilation = stride = 2, rhs_dilation = 1, padding = padding=1, output_padding=1
  // output_padding is handled by adjusting padding or output shape, but StableHLO convolution does not have output_padding attribute.
  // We simulate output_padding by adding padding on the right side of input or adjusting padding.
  // PyTorch ConvTranspose3d formula for output shape:
  // output = (input - 1) * stride - 2*padding + kernel + output_padding
  // Here stride=2, padding=1, kernel=3, output_padding=1
  // So output spatial dims = (input_dim -1)*2 - 2*1 + 3 + 1 = 2*input_dim - 2 + 3 +1 -2 = 2*input_dim
  // So output spatial dims are exactly double input dims, so lhs_dilation=2, padding=1 is correct.

  // dimension_numbers: lhs [b, f, d, h, w], rhs [o, i, kd, kh, kw] -> [b, f, d, h, w]
  // feature_group_count=1, batch_group_count=1

  %conv = "stablehlo.convolution"(%input, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x32x14x14xf32>

  // Add bias: conv + bias broadcasted over batch and spatial dims
  // bias shape: tensor<16xf32>, conv shape: tensor<6x16x32x14x14xf32>
  // Broadcast bias to [1,16,1,1,1]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x32x14x14xf32>

  // 2) MaxPool3d with kernel=2, stride=2, padding=0
  // window_dimensions = [1,1,2,2,2] (batch and channel dims window=1)
  // window_strides = [1,1,2,2,2]
  // padding = 0 for all dims
  // input shape: 6x16x32x14x14
  // output shape: floor((n + 2*pad - window)/stride) + 1
  // spatial dims: depth=32, height=14, width=14
  // output depth = floor((32 - 2)/2) + 1 = 16
