  // Mish activation: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  // Apply twice

  // First Mish
  %exp1 = stablehlo.exponential %conv_bias : tensor<6x7x6x6xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %exp1_plus_one = stablehlo.add %exp1, %one_broadcast : tensor<6x7x6x6xf32>
  %log1p = stablehlo.log %exp1_plus_one : tensor<6x7x6x6xf32>
  %tanh_log1p = stablehlo.tanh %log1p : tensor<6x7x6x6xf32>
  %mish1 = stablehlo.multiply %conv_bias, %tanh_log1p : tensor<6x7x6x6xf32>

  // Second Mish
  %exp2 = stablehlo.exponential %mish1 : tensor<6x7x6x6xf32>
  %exp2_plus_one = stablehlo.add %exp2, %one_broadcast : tensor<6x7x6x6xf32>
  %log1p_2 = stablehlo.log %exp2_plus_one : tensor<6x7x6x6xf32>
  %tanh_log1p_2 = stablehlo.tanh %log1p_2 : tensor<6x7x6x6xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh_log1p_2 : tensor<6x7x6x6xf32>

  return %mish2 : tensor<6x7x6x6xf32>
}

