func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: x * W^T + b
  // %arg0 is linear.weight: tensor<7x7xf32> (out_features x in_features)
  // %arg1 is linear.bias: tensor<7xf32> (out_features)
  // %arg2 is input: tensor<6x7xf32> (batch_size x in_features)
  // We want: output = dot_general(%arg2, transpose(%arg0)) + %arg1
  %0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Actually, %arg0 is 7x7, transpose is 7x7, but we want to multiply input (6x7) by weight^T (7x7)
  // The weight matrix is square, so transpose is still 7x7, but we must do dot_general with contracting dims 1 of lhs and 0 of rhs
  %1 = "stablehlo.dot_general"(%arg2, %0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias from [7] to [6x7]
  %2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>

  // LogSumExp over dim=1, keepdim=True
  // Steps:
  // 1) max over dim=1 (for numerical stability)
  %c_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %4 = "stablehlo.reduce"(%3, %c_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %5 = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%5) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // 2) broadcast max to shape [6x7]
  %6 = "stablehlo.broadcast_in_dim"(%4) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // 3) subtract max for numerical stability
  %7 = stablehlo.subtract %3, %6 : tensor<6x7xf32>
  // 4) exp
  %8 = stablehlo.exponential %7 : tensor<6x7xf32>
  // 5) sum exp over dim=1
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %9 = "stablehlo.reduce"(%8, %c_zero) ({
    ^bb1(%a: tensor<f32>, %b: tensor<f32>):
      %10 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%10) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // 6) log
  %11 = stablehlo.log %9 : tensor<6xf32>
  // 7) add back max
  %12 = stablehlo.add %11, %4 : tensor<6xf32>
  // 8) keepdim=True: broadcast to [6x1]
  %13 = "stablehlo.broadcast_in_dim"(%12) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // LeakyReLU(x) = max(x, 0) + negative_slope * min(x, 0)
  %c_zero_scalar = stablehlo.constant dense<0.0> : tensor<f32>
  %c_slope = stablehlo.constant dense<0.01> : tensor<f32>
  // First LeakyReLU
  %14 = stablehlo.maximum %13, %c_zero_scalar : tensor<6x1xf32>
  %15 = stablehlo.minimum %13, %c_zero_scalar : tensor<6x1xf32>
  %16 = stablehlo.multiply %15, %c_slope : tensor<6x1xf32>
  %17 = stablehlo.add %14, %16 : tensor<6x1xf32>
  // Second LeakyReLU
  %18 = stablehlo.maximum %17, %c_zero_scalar : tensor<6x1xf32>
  %19 = stablehlo.minimum %17, %c_zero_scalar : tensor<6x1xf32>
  %20 = stablehlo.multiply %19, %c_slope : tensor<6x1xf32>
  %21 = stablehlo.add %18, %20 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Precompute constants
  %c_half = stablehlo.constant dense<0.5> : tensor<f32>
  %c_sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // approx sqrt(2)
  // First GELU
  %22 = stablehlo.divide %21, %c_sqrt2 : tensor<6x1xf32>
  %23 = chlo.erf %22 : tensor<6x1xf32>
  %24 = stablehlo.add %23, stablehlo.constant dense<1.0> : tensor<f32> : tensor<6x1xf32>
  %25 = stablehlo.multiply %21, %24 : tensor<6x1xf32>
  %26 = stablehlo.multiply %25, %c_half : tensor<6x1xf32>
  // Second GELU
  %27 = stablehlo.divide %26, %c_sqrt2 : tensor<6x1xf32>
  %28 = chlo.erf %27 : tensor<6x1xf32>
  %29 = stablehlo.add %28, stablehlo.constant dense<1.0> : tensor<f32> : tensor<6x1xf32>
  %30 = stablehlo.multiply %26, %29 : tensor<6x1xf32>
  %31 = stablehlo.multiply %30, %c_half : tensor<6x1xf32>

