func.func @main(%arg0: tensor<6x6x7x8xf32>, %arg1: tensor<6x6x7x8xf32>, %arg2: tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32> {
  // Compute scale = 1 / sqrt(embedding_dimension) = 1 / sqrt(8)
  %c8 = stablehlo.constant dense<8.000000e+00> : tensor<f32>
  %sqrt8 = stablehlo.sqrt %c8 : tensor<f32>
  %one = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  %scale = stablehlo.divide %one, %sqrt8 : tensor<f32>

  // Broadcast scale to shape <6x6x7x7> for QK^T scaling
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<>

  // Transpose K from <6x6x7x8> to <6x6x8x7> to prepare for dot product
  %K_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 0, 1, 3, 2>} : (tensor<6x6x7x8xf32>) -> tensor<6x6x8x7xf32>

  // Compute QK^T: dot_general with contracting dims Q:3, K_t:2 (embedding_dimension)
  %QK = "stablehlo.dot_general"(%arg0, %K_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32>) -> tensor<6x6x7x7xf32>

  // Multiply QK by scale
  %QK_scaled = stablehlo.multiply %QK, %scale_bcast : tensor<6x6x7x7xf32>

  // Compute max for numerical stability: reduce max over last dim (dim=3)
