    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // Broadcast max_val to shape <6x6x7x7> for subtraction
  %max_val_bcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Subtract max_val from QK_scaled
