  // Create a tensor of shape [3] with values [0, 1, 2]
  %range = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<3xi32>

  // Broadcast idx from [8] to [8x3] with broadcast_dimensions = [0]
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<8xi32>) -> tensor<8x3xi32>

  // Broadcast range from [3] to [8x3] with broadcast_dimensions = [1]
  %range_bcast = "stablehlo.broadcast_in_dim"(%range) {broadcast_dimensions = array<i64: 1>} : (tensor<3xi32>) -> tensor<8x3xi32>

  // Compare idx_bcast == range_bcast -> tensor<8x3xi1>
  %cmp = "stablehlo.compare"(%idx_bcast, %range_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<8x3xi32>, tensor<8x3xi32>) -> tensor<8x3xi1>

  // Check idx >= 0 -> tensor<8xi1>
  %ge0 = "stablehlo.compare"(%idx, %c0) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<8xi32>, tensor<i32>) -> tensor<8xi1>

  // Check idx < 3 -> tensor<8xi1>
  %lt3 = "stablehlo.compare"(%idx, %c3) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<8xi32>, tensor<i32>) -> tensor<8xi1>

  // Logical AND of ge0 and lt3 to get valid mask for each row
  %valid_mask = "stablehlo.compare"(%ge0, %lt3) {comparison_direction = #stablehlo<comparison_direction AND>} : (tensor<8xi1>, tensor<8xi1>) -> tensor<8xi1>

  // Broadcast valid_mask from [8] to [8x3] with broadcast_dimensions = [0]
