  %cmp_f32 = "stablehlo.select"(%cmp, %c1, %zero) : (tensor<8x3xi1>, tensor<8x3xf32>, tensor<8x3xf32>) -> tensor<8x3xf32>

  // Final output: select valid_mask_bcast ? cmp_f32 : 0.0
  %out = "stablehlo.select"(%valid_mask_bcast, %cmp_f32, %zero) : (tensor<8x3xi1>, tensor<8x3xf32>, tensor<8x3xf32>) -> tensor<8x3xf32>

  return %out : tensor<8x3xf32>
}

