func.func @main(%arg0: tensor<7x3x3x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x3x7x8x8xf32>) -> tensor<6x7x6x6xf32> {
  // %arg0: conv.weight, shape [7,3,3,3,3]
  // %arg1: conv.bias, shape [7]
  // %arg2: input, shape [6,3,7,8,8]

  // Perform convolution:
  // conv3d with:
  // input shape: [6,3,7,8,8] (NCDHW)
  // weight shape: [7,3,3,3,3] (out_channels, in_channels, kD, kH, kW)
  // output shape: [6,7,5,6,6] because:
  // output_D = 7 - 3 + 1 = 5
  // output_H = 8 - 3 + 1 = 6
  // output_W = 8 - 3 + 1 = 6

  // dimension_numbers: input [N,C,D,H,W] = [0,1,2,3,4]
  // kernel [O,I,kD,kH,kW] = [0,1,2,3,4]
  // output [N,C,D,H,W] = [0,1,2,3,4]

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x7x8x8xf32>, tensor<7x3x3x3x3xf32>) -> tensor<6x7x5x6x6xf32>

  // Add bias: broadcast bias from [7] to [6,7,5,6,6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x5x6x6xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x5x6x6xf32>

  // Apply minimum along dimension 2 (depth dimension after conv)
  // Reduce dimension 2 (size 5) with minimum
  %init_min = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf for min init

  %min = "stablehlo.reduce"(%conv_bias, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x5x6x6xf32>, tensor<f32>) -> tensor<6x7x6x6xf32>

  // Apply softmax along channel dimension (dim=1)
  // softmax(x) = exp(x) / sum(exp(x), dim=1)

  // Step 1: compute exp(x)
  %exp = stablehlo.exponential %min : tensor<6x7x6x6xf32>

  // Step 2: sum(exp(x), dim=1)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>

  %sum_exp = "stablehlo.reduce"(%exp, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x6x6xf32>

  // Broadcast sum_exp from [6,6,6] to [6,7,6,6] for division
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Divide exp by sum_exp to get softmax output
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x7x6x6xf32>

  "stablehlo.return"(%softmax) : tensor<6x7x6x6xf32>
