func.func @main(%arg0: tensor<3x16x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<6x3x16x7x7xf32>) -> tensor<6x16x1x1x1xf32> {
  // Transpose conv_transpose.weight from (in_channels, out_channels, kD, kH, kW) = 3x16x3x3x3
  // to (out_channels, in_channels, kD, kH, kW) = 16x3x3x3x3 for convolution rhs
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c3 = stablehlo.constant dense<3> : tensor<i64>
  %c4 = stablehlo.constant dense<4> : tensor<i64>
  %transposed_weight = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Convolution parameters:
  // Input: %arg2 tensor<6x3x16x7x7xf32> (NCDHW)
  // Weight: %transposed_weight tensor<16x3x3x3x3xf32> (OICDHW)
  // Output shape: (6,16,1,1,1) as given
  // stride=2, padding=1, dilation=1, groups=1
  // dimension_numbers = [b, i, d, h, w] x [o, i, kd, kh, kw] -> [b, o, od, oh, ow]
  %conv = "stablehlo.convolution"(%arg2, %transposed_weight) {
    window_strides = array<i64: 2, 2, 2>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x1x1x1xf32>

  // Add bias: broadcast bias %arg1 (16) to output shape (6x16x1x1x1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<6x16x1x1x1xf32>
  %biased = stablehlo.add %conv, %bias_broadcast : tensor<6x16x1x1x1xf32>

