  %scale = stablehlo.constant dense<0.5> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x16x1x1x1xf32>
  %scaled = stablehlo.multiply %biased, %scale_broadcast : tensor<6x16x1x1x1xf32>

