func.func @main(%bias: tensor<1x16x1x1xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<1x16x16x1xf32> {
  // GEMM: x = input @ gemm_weight^T + gemm_bias
  // gemm_weight shape: [16,16], input shape: [16,16]
  // We want input * gemm_weight^T, so transpose gemm_weight
  %gemm_weight_t = "stablehlo.transpose"(%gemm_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
