  %x_bias = stablehlo.add %x, %gemm_bias : tensor<16x16xf32>

  // GroupNorm with num_groups=16, out_features=16
  // Input shape to GN: [16,16]
  // GN reshapes input to [N, G, C//G] = [16,16,1]
  // Compute mean and variance over last dimension (dim=2)
  // mean = reduce mean over dim=2
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x_bias, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // mean = sum / 1 (since dim=2 size=1)
  // So mean = sum (no division needed)
  %mean = %sum

  // Compute variance = mean((x - mean)^2) over dim=2
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %x_bias_reshaped = "stablehlo.reshape"(%x_bias) : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %x_bias_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %diff_sq_reshaped = "stablehlo.reshape"(%diff_sq) : (tensor<16x16x1xf32>) -> tensor<16x16xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq_reshaped, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum2 = stablehlo.add %a, %b : tensor<f32>
